INSERT INTO alerts (title, message, severity, type, region_id, created_by, created_at) VALUES
  ('Drought emergency: Borena', 'NDVI has fallen to 0.14 and 90-day rainfall is 32% of normal. Activate destocking and water-trucking plans; prioritise lactating females and calves.', 'danger', 'drought', 1, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '1 days 5 hours'),
  ('Rainfall deficit: Shabelle', 'Gode and Kelafo received 37% of normal rainfall. Berkads are drying; expect pressure on Shabelle riverbank grazing.', 'danger', 'drought', 5, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '3 days 7 hours'),
  ('Gode market prices down 18%', 'Goat and sheep prices at Gode market fell 18% in two weeks as households destock. Advise delaying sales of young stock where possible.', 'warning', 'financial', 5, '00000000-0000-4000-8000-000000000001', NOW() - INTERVAL '5 days 8 hours'),
  ('Below-normal kiremt: Afar Zone 1', 'Seasonal rainfall at 41% of normal around Asaita and Dubti. Monitor body condition and water points closely.', 'warning', 'drought', 3, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '8 days 2 hours'),
  ('PPR cases confirmed', 'Peste des petits ruminants confirmed in small ruminants. Isolate affected flocks and request ring vaccination through the woreda vet office.', 'danger', 'disease', 3, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '2 days 4 hours'),
  ('FMD reported near Moyale', 'Foot-and-mouth disease suspected in cattle around Moyale. Avoid shared watering points with unvaccinated herds.', 'warning', 'disease', 1, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '6 days 5 hours'),
  ('Trypanosomiasis season: Guji', 'Tsetse activity rises with the Ganna rains along river grazing. Watch cattle for weight loss and pale gums.', 'warning', 'disease', 2, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '10 days 7 hours'),
  ('Omo river flood watch', 'Upstream rainfall may raise the Omo river within 5 days. Move herds away from low riverbank grazing near Omorate.', 'warning', 'weather', 7, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '4 days 6 hours'),
  ('Deyr rains on track: Fafan', 'Rainfall at 89% of normal and vegetation recovering around Jigjiga and Kebribeyah.', 'success', 'weather', 6, '00000000-0000-4000-8000-00000000000f', NOW() - INTERVAL '7 days 6 hours'),
  ('National PPR & pox vaccination campaign', 'Free PPR and sheep & goat pox vaccination runs for 3 weeks from next Monday. Extension workers: confirm flock lists by Friday.', 'info', 'system', NULL, '00000000-0000-4000-8000-000000000001', NOW() - INTERVAL '2 days 9 hours'),
  ('IBLI sales window open', 'Index-based livestock insurance can be purchased until the end of the month for the coming season.', 'info', 'financial', NULL, '00000000-0000-4000-8000-000000000001', NOW() - INTERVAL '9 days 7 hours');
INSERT INTO alert_reads (alert_id, user_id) SELECT id, '00000000-0000-4000-8000-000000000001' FROM alerts WHERE created_at < NOW() - INTERVAL '6 days';
INSERT INTO inquiries (name, email, organization, interest, message, status, created_at) VALUES
  ('Tsegaye Mulatu', 'tsegaye@borena-coop.example', 'Borena Pastoral Cooperative Union', 'pilot', 'We represent 40 primary cooperatives in Borena and would like to discuss tagging members'' breeding stock before the Deyr season.', 'new', NOW() - INTERVAL '1 days 3 hours'),
  ('Nasra Abdillahi', 'nasra@hornagrifinance.example', 'Horn Agri-Finance', 'finance', 'Interested in using Mobile Vet herd and risk data to underwrite small-ruminant fattening loans in Fafan.', 'contacted', NOW() - INTERVAL '6 days 3 hours'),
  ('Dr. Yonas Haile', 'yonas.haile@vetclinic.example', 'Yabelo Veterinary Clinic', 'veterinary', 'Can private clinics log treatments in the platform? We see many referred cases from Dubluk and Dire.', 'new', NOW() - INTERVAL '2 days 3 hours'),
  ('Martha Gebre', 'martha@resilience-ngo.example', 'Pastoral Resilience Initiative', 'government', 'Exploring a partnership for early-warning SMS in South Omo. Please share pricing for 2,000 households.', 'closed', NOW() - INTERVAL '21 days 3 hours');
